import { FONT_LICENSE } from './font-license.js';
export const escapeXml = (s) => s.replace(/[<>&"']/g, ch => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&apos;' }[ch]));
export function renderSVG(scene, fontBase64, highlight = null) {
    if (!fontBase64)
        throw new Error('A local embedded Liberation Mono font is required for reproducible SVG export.');
    const style = `@font-face{font-family:NAAEMono;src:url(data:font/ttf;base64,${fontBase64}) format('truetype')}text{font-family:NAAEMono,monospace;font-size:${scene.fontSize}px;font-variant-ligatures:none;white-space:pre}`;
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${scene.physicalWidth}mm" height="${scene.physicalHeight}mm" viewBox="0 0 ${scene.width} ${scene.height}" role="img" aria-labelledby="art-title art-desc"${scene.transparent === false ? ` style="background:${scene.background ?? '#101713'}"` : ''}><title id="art-title">${escapeXml(scene.title)}</title><desc id="art-desc">${escapeXml(scene.description)}</desc><metadata>${escapeXml(JSON.stringify(scene.metadata))}</metadata><metadata id="font-license">${escapeXml(FONT_LICENSE)}</metadata><defs><style>${style}</style></defs>${scene.glyphs.map(g => `<text x="${g.x.toFixed(3)}" y="${g.y.toFixed(3)}" fill="${highlight && g.kind === 'narrative' && (g.region ?? g.layer) === highlight ? '#ffcf7f' : g.ink}"${highlight && !(g.kind === 'narrative' && (g.region ?? g.layer) === highlight) ? ' opacity="0.23"' : ''} aria-hidden="true" data-layer="${escapeXml(g.layer)}" data-region="${escapeXml(g.region ?? g.layer)}" data-kind="${g.kind}"${g.textureWord ? ` data-texture-word="${escapeXml(g.textureWord.text)}" data-word-id="${g.textureWord.id}" data-word-index="${g.textureWord.index}" data-word-domain="${escapeXml(g.textureWord.domain)}"` : ''}${g.tileRole ? ` data-tile-role="${g.tileRole}" data-tile-x="${g.tileX}" data-tile-y="${g.tileY}"` : ''}${g.material ? ` data-material="${g.material}" data-intensity="${g.visualIntensity?.toFixed(5)}" data-depth="${g.depth}"` : ''}${g.index !== undefined ? ` data-index="${g.index}" data-passage="${escapeXml(g.passageId ?? g.layer)}" data-order="${g.readingOrder ?? g.index}"` : ''}${g.fontSize ? ` font-size="${g.fontSize}"` : ''} xml:space="preserve">${escapeXml(g.char)}</text>`).join('')}</svg>`;
}
export function renderASCII(cols, rows, glyphs) { const grid = Array.from({ length: rows }, () => Array(cols).fill(' ')); for (const g of glyphs)
    grid[g.row][g.col] = g.char; return grid.map(row => row.join('').trimEnd()).join('\n'); }
